            if r > 5.4 or abs(ang) > 70:
                target = cang
        if abs(target) > 95:
            fwd = -0.5
        elif d > 2.4:
            fwd = 1.0
        elif d > 1.6:
            fwd = 0.8
        elif d > 1.0:
            fwd = 0.55
        else:
            fwd = 0.3
        if r > 5.7:
            if fwd < 0.5:
                fwd = 0.5
        mem = me.memory
        if "dir" not in mem:
            mem["dir"] = 1.0
            mem["last"] = arena.time
        if arena.time - mem["last"] > 2.0:
            mem["dir"] = -mem["dir"]
            mem["last"] = arena.time
        dirn = mem["dir"]
        steer = 0.045 * target
        if steer > 0.9:
            steer = 0.9
        elif steer < -0.9:
            steer = -0.9
        if d < 1.4:
            steer = steer + 0.35 * dirn
        if steer > 1.0:
            steer = 1.0
        elif steer < -1.0:
            steer = -1.0
        left = fwd - steer
        right = fwd + steer
        if left > 1.0:
            left = 1.0
        elif left < -1.0:
            left = -1.0
        if right > 1.0:
            right = 1.0
        elif right < -1.0:
            right = -1.0
        return (left, right)
    except Exception:
        return (0.0, 0.0)

